export type BufferIndicatorState = {
    type: 'idle';
} | {
    type: 'pending';
} | {
    type: 'showing';
};
export type BufferIndicatorEvent = {
    type: 'buffer-start';
    delayInMilliseconds: number;
} | {
    type: 'buffer-end';
} | {
    type: 'delay-elapsed';
};
export type BufferIndicatorEffect = 'start-timer' | 'clear-timer' | null;
export declare const reduceBufferIndicator: (state: BufferIndicatorState, event: BufferIndicatorEvent) => {
    state: BufferIndicatorState;
    effect: BufferIndicatorEffect;
};
